+    const q = Number(String(quantidade).replace(",", "."));
+    if (!Number.isFinite(q) || q <= 0) e.quantidade = "Informe um número > 0";
+    setErros(e);
+    if (Object.keys(e).length) return;
+
+    const hora = new Date().toLocaleTimeString();
+    setItens(prev => {
+      const idx = prev.findIndex(x => x.codigo === codbarras.trim());
+      if (idx >= 0) {
+        const clone = [...prev];
+        const it = clone[idx];
+        const atualizado: Item = {
+          ...it, qtd: it.qtd + q, hora,
+          cod: cod || it.cod, nome: nome || it.nome,
