+
+      {/* Modal: adicionar manual */}
+      <Modal visible={modalVisivel} transparent animationType="fade" onRequestClose={() => setModalVisivel(false)}>
+        <View style={s.backdrop}>
+          <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : undefined} style={s.modalCard}>
+            <Text style={s.modalTitle}>Adicionar item</Text>
+
+            <Text style={s.label}>cod (opcional)</Text>
+            <TextInput value={cod} onChangeText={setCod} placeholder="Ex.: 12345" style={s.input} autoCapitalize="none" />
+
+            <Text style={s.label}>codbarras *</Text>
+            <TextInput
+              value={codbarras}
+              onChangeText={setCodbarras}
+              placeholder="Ex.: 7891234567890"
+              style={[s.input, erros.codbarras && s.inputError]}
+              autoCapitalize="none"
+              keyboardType="numeric"
+            />
+            {erros.codbarras ? <Text style={s.errText}>{erros.codbarras}</Text> : null}
+
+            <Text style={s.label}>nome *</Text>
+            <TextInput value={nome} onChangeText={setNome} placeholder="Ex.: Ração Premium 20kg" style={[s.input, erros.nome && s.inputError]} />
