+// Remove CR/LF/TAB e colapsa "CODECODE" => "CODE"
+function normalizeScan(raw: string) {
+  let s = raw.replace(/[\r\n\t]+/g, "").trim();
+  const n = s.length;
+  if (n % 2 === 0) {
+    const half = n / 2;
+    const a = s.slice(0, half);
+    const b = s.slice(half);
+    if (a === b) s = a; // leitor enviou duas vezes no MESMO disparo
+  }
+  return s;
+}
+
+export default function Contagem() {
