+// Remove CR/LF/TAB e colapsa "CODECODE" => "CODE"
+function normalizeScan(raw: string) {
+  let s = raw.replace(/[\r\n\t]+/g, "").trim();
+
+  // se houver dígitos, prioriza só os dígitos (evita sufixos/prefixos do leitor)
+  const onlyDigits = s.replace(/\D+/g, "");
+  if (onlyDigits.length >= 8) s = onlyDigits;
+
+  // colapsa padrão repetido (menor período da string)
+  // técnica do (s+s).indexOf(s, 1) < s.length => tem repetição
+  const n = s.length;
+  if (n > 0) {
+    const ss = (s + s).slice(1, -1);
+    const i = ss.indexOf(s);
+    if (i !== -1) {
+      const period = i + 1;
+      if (n % period === 0) s = s.slice(0, period);
+    }
+  }
+  return s;
+}
+
+export default function Contagem() {
+  const isFocused = useIsFocused();
+
+  const [itens, setItens] = useState<Item[]>([]);
+  const [busca, setBusca] = useState("");
