+  const [nome, setNome] = useState("");
+  const [quantidade, setQuantidade] = useState("");
+  const [erros, setErros] = useState<{ codbarras?: string; nome?: string; quantidade?: string }>({});
+
+  // --- Modal de CONFIRMAR excluir ---
