+
+  // --- KPIs ---
+  const produtosDiferentes = useMemo(
+    () => new Set(itens.filter(i => i.qtd > 0).map(i => i.codigo)).size,
+    [itens]
+  );
+  const quantidadeTotal = useMemo(() => itens.reduce((s, i) => s + i.qtd, 0), [itens]);
+  const ultimoProdutoTxt = useMemo(() => (itens.length ? (itens[0].nome || itens[0].codigo) : "—"), [itens]);
+
+  // --- Busca (cod, codbarras, nome) ---
+  const itensFiltrados = useMemo(() => {
+    const q = busca.trim().toLowerCase();
+    if (!q) return itens;
+    return itens.filter(it =>
+      (it.cod ?? "").toLowerCase().includes(q) ||
+      it.codigo.toLowerCase().includes(q) ||
+      it.nome.toLowerCase().includes(q)
+    );
+  }, [busca, itens]);
+
+  // ---------- Commit de leitura robusto ----------
+    function commitScan(raw: string) {
+    const code = normalizeScan(raw);
+    if (!code) return;
+
+    const now = Date.now();
+    if (code === lastScanRef.current.code && now - lastScanRef.current.t < DEDUPE_MS) return;
+    lastScanRef.current = { code, t: now };
+
+    const hora = new Date().toLocaleTimeString();
