+    setTargetNome(nome ?? codigo);
+    setConfirmVisible(true);
+  }
+
+  function confirmarExcluir() {
+    if (!targetCodigo) return;
+    setItens(prev => prev.filter(x => x.codigo !== targetCodigo));
+    setConfirmVisible(false);
+    setTargetCodigo(null);
+    setTargetNome(null);
+  }
