+  );
+
+  const renderItem: ListRenderItem<Item> = ({ item }) => (
+    <Swipeable renderRightActions={() => <DeleteAction onPress={() => pedirConfirmacaoExcluir(item.codigo, item.nome)} />} overshootRight={false}>
