+
+    setCod(""); setCodbarras(""); setNome(""); setQuantidade(""); setErros({});
+    setModalVisivel(false);
+  }
+
+  return (
+    <GestureHandlerRootView
+      style={{ flex: 1, backgroundColor: "#fff" }}
+      onTouchStart={focusReader} // qualquer toque volta o foco para o leitor
+    >
+      {/* Input invisível do leitor externo */}
+      {externalReader && (
+        <TextInput
+          ref={readerRef}
+          value={readerBuffer}
+          onChangeText={onReaderChange}     // usa buffer + silêncio
+          style={s.hiddenInput}
