+                <Text style={s.btnTextDanger}>Excluir</Text>
+              </TouchableOpacity>
+            </View>
+          </View>
+        </View>
+      </Modal>
+    </GestureHandlerRootView>
+  );
+}
+
+/* ---- componentes auxiliares ---- */
