import { BarCodeScanner } from "expo-barcode-scanner";
import * as FileSystem from "expo-file-system";
import * as Sharing from "expo-sharing";
import { useEffect, useMemo, useState } from "react";
import { FlatList, StyleSheet, Text, TouchableOpacity, View } from "react-native";

type Item = { codigo: string; qtd: number; hora: string };

export default function Contagem() {
  const [temPermissao, setTemPermissao] = useState<boolean | null>(null);
  const [scanning, setScanning] = useState(true);
  const [items, setItems] = useState<Item[]>([]);

  useEffect(() => {
    (async () => {
      const { status } = await BarCodeScanner.requestPermissionsAsync();
      setTemPermissao(status === "granted");
    })();
  }, []);

  const onScan = ({ data }: { data: string }) => {
    if (!scanning) return;
    setScanning(false);
    setItems((prev) => {
      const i = prev.findIndex((x) => x.codigo === data);
      const hora = new Date().toLocaleTimeString();
      if (i >= 0) {
        const clone = [...prev];
        clone[i] = { ...clone[i], qtd: clone[i].qtd + 1, hora };
        return clone;
      }
      return [{ codigo: data, qtd: 1, hora }, ...prev];
    });
    setTimeout(() => setScanning(true), 600); // evita leituras duplicadas
  };

  const total = useMemo(() => items.reduce((s, it) => s + it.qtd, 0), [items]);

  const exportCsv = async () => {
    const header = "codigo;qtd;hora\n";
    const lines = items.map((it) => `${it.codigo};${it.qtd};${it.hora}`).join("\n");
    const csv = header + lines;
    const path = FileSystem.cacheDirectory + `contagem_${Date.now()}.csv`;
    await FileSystem.writeAsStringAsync(path, csv, {
      encoding: FileSystem.EncodingType.UTF8,
    });
    await Sharing.shareAsync(path);
  };

  if (temPermissao === null)
    return <View style={s.center}><Text>Pedindo permissão da câmera…</Text></View>;
  if (temPermissao === false)
    return <View style={s.center}><Text>Sem acesso à câmera. Habilite nas permissões do app.</Text></View>;

  return (
    <View style={{ flex: 1 }}>
      <View style={{ height: 280, overflow: "hidden", borderBottomWidth: StyleSheet.hairlineWidth }}>
        <BarCodeScanner onBarCodeScanned={onScan} style={{ width: "100%", height: "100%" }} />
      </View>

      <View style={s.row}>
        <Text style={s.title}>Itens: {items.length} • Total: {total}</Text>
        <TouchableOpacity onPress={() => setItems([])}>
          <Text style={s.link}>Limpar</Text>
        </TouchableOpacity>
        <TouchableOpacity onPress={exportCsv}>
          <Text style={s.link}>Exportar CSV</Text>
        </TouchableOpacity>
      </View>

      <FlatList
        data={items}
        keyExtractor={(it) => it.codigo}
        contentContainerStyle={{ padding: 12 }}
        renderItem={({ item }) => (
          <View style={s.item}>
            <Text style={s.itemCodigo}>{item.codigo}</Text>
            <View style={s.itemRight}>
              <TouchableOpacity
                onPress={() =>
                  setItems((prev) =>
                    prev.map((x) =>
                      x.codigo === item.codigo ? { ...x, qtd: Math.max(0, x.qtd - 1) } : x
                    )
                  )
                }
              >
                <Text style={s.btn}>-</Text>
              </TouchableOpacity>
              <Text style={s.qtd}>{item.qtd}</Text>
              <TouchableOpacity
                onPress={() =>
                  setItems((prev) =>
                    prev.map((x) => (x.codigo === item.codigo ? { ...x, qtd: x.qtd + 1 } : x))
                  )
                }
              >
                <Text style={s.btn}>+</Text>
              </TouchableOpacity>
            </View>
          </View>
        )}
      />
    </View>
  );
}

const s = StyleSheet.create({
  center: { flex: 1, alignItems: "center", justifyContent: "center" },
  row: { flexDirection: "row", alignItems: "center", gap: 16, padding: 12 },
  title: { fontSize: 16, fontWeight: "600" },
  link: { marginLeft: 12, fontSize: 14, textDecorationLine: "underline" },
  item: { flexDirection: "row", alignItems: "center", paddingVertical: 10, borderBottomWidth: StyleSheet.hairlineWidth },
  itemCodigo: { flex: 1, fontSize: 16 },
  itemRight: { flexDirection: "row", alignItems: "center", gap: 8 },
  btn: { fontSize: 22, paddingHorizontal: 8 },
  qtd: { minWidth: 24, textAlign: "center", fontSize: 16 },
});
